        if let Ok(stats) = index.vector_store.stats(rtxn, &config.name) {
            number_of_embeddings += stats.number_of_embeddings;
            number_of_embedded_documents += stats.number_of_embedded_documents;
        }
    }

    Ok(IndexStats {
        documents_database_stats,
        number_of_documents: Some(number_of_documents),
        database_size,
        number_of_embeddings: Some(number_of_embeddings),
        number_of_embedded_documents: Some(number_of_embedded_documents),
        used_database_size,
        primary_key,
        field_distribution,
        created_at,
        updated_at,
    })
}
