    match &self.value_kind {
        ValueKind::Single(value_path) => {
            let value = values.next().ok_or(MissingValue)?;
            let mut rendered = self.template.clone();
            inject_value(&mut rendered, value_path, value);
            Ok(rendered)
        }
        ValueKind::Array(array_path) => {
            let array_values: Vec<Value> = values
                .map(|v| {
                    let mut repeated = array_path.repeated_value.clone();
                    inject_value(&mut repeated, &array_path.value_path_in_array, v);
                    repeated
                })
                .collect();
            if array_values.is_empty() {
                return Err(MissingValue);
            }
            let mut rendered = self.template.clone();
            inject_value(&mut rendered, &array_path.path_to_array, Value::Array(array_values));
            Ok(rendered)
        }
    }
